solution:
import heapq

def startup_order(dependencies):
    counts = {name: len(items) for name, items in dependencies.items()}
    dependents = {name: [] for name in dependencies}
    for name, items in dependencies.items():
        for dependency in items:
            dependents[dependency].append(name)
    ready = [name for name, count in counts.items() if count == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        name = heapq.heappop(ready)
        result.append(name)
        for dependent in dependents[name]:
            counts[dependent] -= 1
            if counts[dependent] == 0:
                heapq.heappush(ready, dependent)
    return result if len(result) == len(dependencies) else None

