solution:
def peak_concurrency(intervals):
    events = []
    for start, end in intervals:
        if start < end:
            events.extend([(start, 1), (end, -1)])
    current = peak = 0
    for _, delta in sorted(events):
        current += delta
        peak = max(peak, current)
    return peak

